class ConnectGame:
    def __init__(self, board):
        """
        board: either a single string with newline-separated rows, or a list/tuple of strings.
        Each row visually may be indented; cells are characters '.' 'O' 'X' possibly separated by spaces.
        We parse each row by removing whitespace except the cell characters.
        """
        # Normalize input to list of lines
        if board is None:
            board_lines = []
        elif isinstance(board, str):
            board_lines = board.splitlines()
        else:
            # assume iterable of strings
            board_lines = list(board)

        grid = []
        for line in board_lines:
            # extract only the cell characters (.,O,X)
            row = [ch for ch in line if ch in ".OX"]
            if row:
                grid.append(row)
        self.grid = grid
        self.R = len(grid)
        self.C = len(grid[0]) if self.R > 0 else 0

    def _neighbors(self, r, c):
        # hex neighbors for this representation (parallelogram with rows indented)
        deltas = [(-1, 0), (1, 0), (0, -1), (0, 1), (-1, 1), (1, -1)]
        for dr, dc in deltas:
            nr, nc = r + dr, c + dc
            if 0 <= nr < self.R and 0 <= nc < self.C:
                yield nr, nc

    def _has_path(self, player):
        if self.R == 0 or self.C == 0:
            return False
        from collections import deque
        q = deque()
        visited = [[False] * self.C for _ in range(self.R)]

        if player == 'O':
            # O connects top (row 0) to bottom (row R-1)
            for c in range(self.C):
                if self.grid[0][c] == 'O':
                    q.append((0, c))
                    visited[0][c] = True
            target_row = self.R - 1
            while q:
                r, c = q.popleft()
                if r == target_row:
                    return True
                for nr, nc in self._neighbors(r, c):
                    if not visited[nr][nc] and self.grid[nr][nc] == 'O':
                        visited[nr][nc] = True
                        q.append((nr, nc))
            return False

        elif player == 'X':
            # X connects left (col 0) to right (col C-1)
            for r in range(self.R):
                if self.grid[r][0] == 'X':
                    q.append((r, 0))
                    visited[r][0] = True
            target_col = self.C - 1
            while q:
                r, c = q.popleft()
                if c == target_col:
                    return True
                for nr, nc in self._neighbors(r, c):
                    if not visited[nr][nc] and self.grid[nr][nc] == 'X':
                        visited[nr][nc] = True
                        q.append((nr, nc))
            return False
        else:
            return False

    def get_winner(self):
        """
        Returns:
          - 'O' if only O has a connecting path top-to-bottom
          - 'X' if only X has a connecting path left-to-right
          - "" (empty string) if neither has a path or if both have paths (ambiguous/unfair board)
        """
        o_win = self._has_path('O')
        x_win = self._has_path('X')
        if o_win and not x_win:
            return 'O'
        if x_win and not o_win:
            return 'X'
        return ""
